[
  {
    "statement": "Setting and enforcing vessel speed limits appears to be the only intervention with demonstrated effectiveness for reducing lethal vessel strikes on large whales.",
    "citations": [
      "2777"
    ]
  },
  {
    "statement": "Two studies have evaluated the method of setting and enforcing vessel speed limits.",
    "citations": [
      "2777"
    ]
  },
  {
    "statement": "In the North Atlantic Ocean, setting vessel speed limits during specific periods in key habitats resulted in fewer North Atlantic right whale deaths caused by collisions.",
    "citations": []
  },
  {
    "statement": "In the Indian River estuarine system, fewer manatee deaths were recorded after speed limits were set and enforced in all areas.",
    "citations": []
  },
  {
    "statement": "Diverting shipping routes is a potential intervention for reducing vessel strikes.",
    "citations": [
      "2754"
    ]
  },
  {
    "statement": "Using observers on board vessels to detect mammals and allow a vessel's course or speed to be altered is a potential intervention.",
    "citations": [
      "2755"
    ]
  },
  {
    "statement": "Using remote tools to detect mammals in an area and allow a vessel's course or speed to be altered is a potential intervention.",
    "citations": [
      "2757"
    ]
  },
  {
    "statement": "Reducing shipping along inland waterways is a potential intervention.",
    "citations": [
      "2763"
    ]
  },
  {
    "statement": "Designating Particularly Sensitive Sea Areas to regulate impactful maritime activities is a potential intervention.",
    "citations": [
      "2223"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effects of alternative approaches, such as diverting shipping routes or using observers, on marine mammal populations.",
    "citations": []
  },
  {
    "statement": "Limiting vessel speeds was found to be effective for reptiles.",
    "citations": [
      "3531"
    ]
  },
  {
    "statement": "Vessels travelling at lower speeds caused fewer catastrophic injuries to artificial loggerhead turtle shells.",
    "citations": [
      "3531"
    ]
  },
  {
    "statement": "Fewer boat-related injuries to spectacled caiman occurred in waterways with enforced speed limits.",
    "citations": [
      "3531"
    ]
  }
]

[
  {
    "statement": "There is limited direct evidence about the long-term impact of climate change on the effectiveness of legally protected marine areas for cetaceans.",
    "citations": []
  },
  {
    "statement": "Legally protecting areas where climate change impacts are predicted to be less severe has not been evaluated in any studies for marine and freshwater mammal populations.",
    "citations": [
      "2912"
    ]
  },
  {
    "statement": "Creating marine protected areas or setting legal protection levels where natural climate refugia occur to promote species persistence and recovery facing climate change has not been evaluated in any studies.",
    "citations": [
      "2222"
    ]
  },
  {
    "statement": "Establishing networks of legally protected areas lacks direct evaluation studies for marine and freshwater mammal populations.",
    "citations": [
      "2913"
    ]
  },
  {
    "statement": "There is some evidence on the effectiveness of legally protecting habitat for marine and freshwater mammals.",
    "citations": [
      "2915"
    ]
  },
  {
    "statement": "Four studies on the effectiveness of legally protecting habitat for marine and freshwater mammals found varied results.",
    "citations": [
      "2915"
    ]
  },
  {
    "statement": "One study in the North Atlantic Ocean found Mediterranean monk seal populations increased during eight years after legal protection.",
    "citations": [
      "2915"
    ]
  },
  {
    "statement": "A North Sea study found bottlenose dolphin populations remained similar in size before and after protection.",
    "citations": [
      "2915"
    ]
  },
  {
    "statement": "A South Pacific Ocean study found higher survival rates for Hector's dolphins after coastal legal protection.",
    "citations": [
      "2915"
    ]
  },
  {
    "statement": "A Port River estuary study showed reduced human-caused strandings of Indo-Pacific bottlenose dolphins after legal protection was established.",
    "citations": [
      "2915"
    ]
  }
]

[
  {
    "statement": "The action documents do not contain specific information about public education campaigns targeting plastic litter ingestion by river dolphins in South America.",
    "citations": []
  },
  {
    "statement": "Educational whale-watching tours in the South Pacific Ocean in Peru resulted in participants being more willing to cut their fishing nets to save entangled dolphins.",
    "citations": [
      "2935"
    ]
  },
  {
    "statement": "The educational whale-watching tours in Peru specifically addressed dolphin entanglement rather than plastic ingestion.",
    "citations": [
      "2935"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effects of removing litter from marine and freshwater environments on marine and freshwater mammal populations.",
    "citations": [
      "2895"
    ]
  },
  {
    "statement": "Most captive-born Amazon river dolphins did not survive in captivity in the USA, China, Indonesia and Venezuela.",
    "citations": [
      "2932"
    ]
  },
  {
    "statement": "Multimedia campaigns have resulted in successful conservation education programs for various primate species in different countries.",
    "citations": [
      "1571"
    ]
  },
  {
    "statement": "The successful conservation education programs for primate species did not specifically address marine mammals or plastic pollution.",
    "citations": [
      "1571"
    ]
  },
  {
    "statement": "Education and awareness campaigns could be effective for reptile conservation.",
    "citations": [
      "3682"
    ]
  },
  {
    "statement": "Examples of reptile conservation campaigns have shown reduced killing and increased survival rates for the animals.",
    "citations": [
      "3682"
    ]
  },
  {
    "statement": "The effective education and awareness campaigns for reptile conservation did not address marine mammals or plastic pollution specifically.",
    "citations": [
      "3682"
    ]
  }
]
